export function createRawRebuildInputBundle(value){if(!value||typeof value!=="object")throw new Error("REBUILD_INPUT_INVALID");return Object.freeze({...value,rawEvents:Object.freeze([...(value.rawEvents||[])])});}
export function validateRebuildRequest({scopeType,companyId,projectId=null,currency}){if(!(scopeType==="COMPANY"||scopeType==="PROJECT")||typeof companyId!=="string"||!companyId||typeof currency!=="string"||!currency||(scopeType==="COMPANY"&&projectId!=null)||(scopeType==="PROJECT"&&(!projectId||typeof projectId!=="string")))throw new Error("REBUILD_INPUT_INVALID");return true;}
